<?php
/** Workbench v9.1.0 — Experimental Design & Research Protocol Builder. */
if (!defined('ABSPATH')) { exit; }
function scwb_v910_backend_request($path,$method='GET',$body=null){$base=defined('SCWB_BACKEND_URL')?rtrim(SCWB_BACKEND_URL,'/'):rtrim((string)get_option('scwb_backend_url','https://workbench-api.sustainablecatalyst.com'),'/');$args=array('method'=>$method,'timeout'=>30,'headers'=>array('Accept'=>'application/json','Content-Type'=>'application/json'));if($body!==null){$args['body']=wp_json_encode($body);} $r=wp_remote_request($base.$path,$args);if(is_wp_error($r)){return array('ok'=>false,'error'=>$r->get_error_message(),'_httpStatus'=>502);} $code=wp_remote_retrieve_response_code($r);$d=json_decode(wp_remote_retrieve_body($r),true);if(!is_array($d)){$d=array('ok'=>false,'error'=>'Invalid backend response');}$d['_httpStatus']=$code;return $d;}
function scwb_v910_status_shortcode(){ $r=scwb_v910_backend_request('/v910/status'); return '<pre class="scwb-v910-status">'.esc_html(wp_json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)).'</pre>'; }
add_shortcode('sc_workbench_research_protocol_builder_status','scwb_v910_status_shortcode');
function scwb_v910_protocol_shortcode($atts){$atts=shortcode_atts(array('project'=>'','study_hash'=>''),$atts,'sc_workbench_research_protocol_builder');$project=sanitize_text_field($atts['project']);$study=sanitize_text_field($atts['study_hash']);$uid='scwb-v910-'.wp_generate_uuid4();ob_start();?>
<div id="<?php echo esc_attr($uid); ?>" class="scwb-v910" data-nonce="<?php echo esc_attr(wp_create_nonce('wp_rest')); ?>"><style>.scwb-v910{border:1px solid #d7d7d7;padding:20px;border-radius:12px;font-family:system-ui,sans-serif}.scwb-v910 .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:10px}.scwb-v910 input,.scwb-v910 textarea,.scwb-v910 select{width:100%;box-sizing:border-box;padding:8px}.scwb-v910 button{padding:9px 14px;margin:8px 8px 8px 0}.scwb-v910 pre{max-height:560px;overflow:auto;background:#111;color:#d8ffd8;padding:12px;border-radius:8px}</style><small>SUSTAINABLE CATALYST WORKBENCH · V9.1.0</small><h3>Experimental Design & Research Protocol Builder</h3><div class="grid"><label>Project key<input data-f="projectKey" value="<?php echo esc_attr($project); ?>"></label><label>Study hash<input data-f="studyHash" value="<?php echo esc_attr($study); ?>"></label><label>Protocol key<input data-f="protocolKey" placeholder="protocol-001"></label><label>Title<input data-f="title"></label><label>Status<select data-f="status"><option>draft</option><option>preregistered</option><option>amended</option><option>locked</option></select></label></div><div class="grid"><label>Hypotheses (one per line)<textarea data-f="hypotheses"></textarea></label><label>Variables: id|label|role|datatype|unit<textarea data-f="variables"></textarea></label><label>Arms: id|label|kind|intervention<textarea data-f="arms"></textarea></label><label>Population<textarea data-f="population"></textarea></label><label>Target sample size<input data-f="targetSampleSize" type="number"></label><label>Primary outcome IDs (one per line)<textarea data-f="primaryOutcomeIds"></textarea></label><label>Statistical methods (one per line)<textarea data-f="statisticalMethods"></textarea></label><label>Primary estimand<textarea data-f="primaryEstimand"></textarea></label><label>Stopping target<textarea data-f="stoppingTarget"></textarea></label><label>Preregistration ref<input data-f="preregistrationRef"></label></div><button type="button" data-action="compose">Compose protocol</button><button type="button" data-action="save">Save content-addressed protocol</button><span data-role="status"></span><pre data-role="output">{}</pre><script>(()=>{const r=document.getElementById(<?php echo wp_json_encode($uid); ?>),q=n=>r.querySelector(`[data-f="${n}"]`),lines=n=>(q(n).value||'').split(/\n/).map(x=>x.trim()).filter(Boolean);const body=()=>({projectKey:q('projectKey').value.trim(),studyHash:q('studyHash').value.trim(),protocolKey:q('protocolKey').value.trim(),title:q('title').value.trim(),status:q('status').value,hypotheses:lines('hypotheses').map((x,i)=>({hypothesisId:`h${i+1}`,statement:x,kind:i?'secondary':'primary'})),variables:lines('variables').map(x=>{const p=x.split('|');return {variableId:(p[0]||'').trim(),label:(p[1]||p[0]||'').trim(),role:(p[2]||'covariate').trim(),dataType:(p[3]||'continuous').trim(),unit:(p[4]||'').trim()}}),arms:lines('arms').map(x=>{const p=x.split('|');return {armId:(p[0]||'').trim(),label:(p[1]||p[0]||'').trim(),kind:(p[2]||'treatment').trim(),intervention:(p[3]||'').trim(),allocationWeight:1}}),sampling:{population:q('population').value.trim(),method:'unspecified',targetSampleSize:q('targetSampleSize').value?Number(q('targetSampleSize').value):null},measurement:{primaryOutcomeIds:lines('primaryOutcomeIds')},analysis:{primaryEstimand:q('primaryEstimand').value.trim(),statisticalMethods:lines('statisticalMethods')},stopping:{ruleType:'fixed',target:q('stoppingTarget').value.trim()},preregistrationRef:q('preregistrationRef').value.trim()});const api=async(path,p)=>{const x=await fetch(<?php echo wp_json_encode(rest_url('sc-workbench/v1/v910')); ?>+path,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-WP-Nonce':r.dataset.nonce},body:JSON.stringify(p)});return await x.json();};const run=async(a)=>{r.querySelector('[data-role="status"]').textContent='Working…';const p=body();if(a==='save'){p.createdBy='wordpress';p.recordLabel='Research protocol';}const out=await api(a==='save'?'/protocols':'/compose',p);r.querySelector('[data-role="output"]').textContent=JSON.stringify(out,null,2);r.querySelector('[data-role="status"]').textContent=out.ok?'Ready':'Error';};r.querySelector('[data-action="compose"]').onclick=()=>run('compose');r.querySelector('[data-action="save"]').onclick=()=>run('save');})();</script></div><?php return ob_get_clean();}
add_shortcode('sc_workbench_research_protocol_builder','scwb_v910_protocol_shortcode');
add_action('rest_api_init',function(){$perm=function(){return current_user_can('edit_posts');};register_rest_route('sc-workbench/v1/v910','/compose',array('methods'=>'POST','permission_callback'=>$perm,'callback'=>function($r){$x=scwb_v910_backend_request('/protocol-builder/compose','POST',$r->get_json_params());$st=intval($x['_httpStatus']??200);unset($x['_httpStatus']);return new WP_REST_Response($x,$st);}));register_rest_route('sc-workbench/v1/v910','/protocols',array('methods'=>'POST','permission_callback'=>$perm,'callback'=>function($r){$x=scwb_v910_backend_request('/protocol-builder/protocols','POST',$r->get_json_params());$st=intval($x['_httpStatus']??200);unset($x['_httpStatus']);return new WP_REST_Response($x,$st);}));});
